mapper.select:
select id, keyword, search_count, last_search_at
from sys_search_history
where user_id = #{userId}
order by last_search_at desc, id desc
limit #{limit}

mapper.update:
update sys_search_history
set search_count = search_count + 1,
    last_search_at = now()
where user_id = #{userId}
  and keyword = #{keyword}

mapper.delete:
delete from sys_search_history
where id = #{id}
  and user_id = #{userId}
